"""Names for independently saved evidence pages; never substitute another question."""
PAGE_VIEWS = {'intervention_response_overview': {'coverage': ('coverage', 'status_matrix'), 'before_after': ('before_after',), 'changes': ('original_changes', 'model_effects'), 'controls': ('controls',)}, 'intervention_response_timing': {'response': ('response_delay',), 'recovery': ('recovery',), 'coverage': ('coverage',)}, 'intervention_rhythm_changes': {'period': ('window_period',), 'amplitude': ('window_amplitude',), 'contrasts': ('direct_change',)}, 'intervention_sample_effects': {'changes': ('sample_changes',), 'controls': ('control_effects',), 'coverage': ('coverage',)}, 'intervention_response_patterns': {'cells': ('cell_pairs',), 'outcomes': ('joint_outcomes',), 'samples': ('sample_pairs',), 'recurrence': ('recurrence',)}, 'cell_state_time_summaries': {'occupancy': ('occupancy',), 'switches': ('switch_rates',), 'transitions': ('transitions',), 'bouts': ('bouts',)}, 'state_sample_comparisons': {'samples': ('samples',), 'contrasts': ('contrasts',)}, 'spatial_coordination_overview': {'coverage': ('coverage',), 'geometry': ('effects', 'matrices', 'proximity'), 'timing': ('timing',), 'recordings': ('recordings',)}, 'spatial_coordination_samples': {'samples': ('samples',), 'contrasts': ('contrasts',), 'timing': ('sample_timing',)}, 'measurement_relationship_overview': {'within_cells': ('within_cell',), 'between_cells': ('between_cells',), 'delays': ('delay',)}, 'spatial_coordination_pair_card': {'traces': ('core', 'representation'), 'relationships': ('lag', 'proximity'), 'rhythms': ('rhythm',), 'states': ('states',)}}


def views(key,kind,drawing,table):
    groups=PAGE_VIEWS.get(key,{})
    return {name:(drawing,table) for name,kinds in groups.items() if kind in kinds}
